 path=R/'ttt_joint_1000_v115/report.py';text=path.read_text();node=next(n for n in ast.parse(text).body if isinstance(n,ast.FunctionDef) and n.name=='plot_trace');original=ast.get_source_segment(text,node);adapted=original.replace("label='Final TTT Q(s, executed residual)'","label='Unchanged anchor Q (diagnostic)'").replace("fig.suptitle(f'{region.capitalize()} friction | development task {tid} | friction={spec[\"friction\"]:.5f}',y=.98)","fig.suptitle(f'{spec[\"method_label\"]} | {spec[\"region_label\"]} friction | {spec[\"cohort\"]} task {tid} | friction={spec[\"friction\"]:.5f}',y=.98)").replace("'Continuation: +12500 Q / +6250 actor / +1250 writer updates; fixed base across six trials. No returns enter TTT.'","'T1 excluded from pooled metrics; 12 trials shown. OOD only; frozen slow weights; original anchor Q is diagnostic, not the correction objective.'").replace("text=f'T{ti+1}: G={g:+.3f}' if g is not None else f'T{ti+1}: censored'","text=f'T{ti+1}\\nG={g:+.3f}' if g is not None else f'T{ti+1}\\ncensored'").replace('fontsize=10)','fontsize=8)');assert original!=adapted and '12500' not in adapted;ns=dict(np=np,plt=plt,csv=csv,M=folder);exec(compile(adapted,str(path)+'::plot_trace','exec'),ns);return ns['plot_trace'],dict(parent_plot_source_sha256=sha(path),original_function_sha256=hashlib.sha256(original.encode()).hexdigest(),adapted=adapted)
